New-AzureADMSGroup -DisplayName "SG_All_Exept_EOO" -Description "Beveiligingsgroep tbv CA, waardoor EOO wordt vrijgesteld van ca" -MailEnabled $False -MailNickName "group" -SecurityEnabled $True -GroupTypes "DynamicMembership" -MembershipRule "(user.userPrincipalName -notContains ""eooadmin"" and user.userprincipalname -notcontains ""eoo.cloud"")" -MembershipRuleProcessingState "On"